func Identity() m5.Identity {
	return m5.Identity{SnapshotVersion: m5.SnapshotVersion, SnapshotHash: snapshotHash, SchemaVersion: m5.SchemaVersion, RowCount: len(products)}
}
func FindByID(id uint32) (m5.Product, bool) {
	if id < m5.FirstProductID {
		return m5.Product{}, false
	}
	i := int(id - m5.FirstProductID)
	if i < 0 || i >= len(products) || products[i].ID != id {
		return m5.Product{}, false
	}
	return products[i], true
}
func FindByCategoryD(c m5.Category) m5.Cursor { return m5.CategoryScanCursor(products[:], c) }
func PriceBetweenD(low, high uint32) m5.Cursor {
	if high < low {
		return m5.Cursor{}
	}
	return m5.PriceScanCursor(products[:], low, high)
}
func ActiveRegionD(r m5.Region) m5.ProjectionCursor { return m5.ActiveRegionScanCursor(products[:], r) }
func FindByCategoryE(c m5.Category) m5.Cursor {
	if c >= m5.CategoryCount {
		return m5.Cursor{}
	}
	a, b := categoryOffsets[c], categoryOffsets[c+1]
	return m5.IDsCursor(products[:], categoryRows[a:b])
}
func PriceBetweenE(low, high uint32) m5.Cursor {
	if high < low {
		return m5.Cursor{}
	}
	return m5.SortedPriceCursor(products[:], priceRows[:], low, high)
}
func ActiveRegionE(r m5.Region) m5.ProjectionCursor {
	if r >= m5.RegionCount {
		return m5.ProjectionCursor{}
	}
	a, b := activeOffsets[r], activeOffsets[r+1]
	return m5.ProjectionsCursor(activeProjections[a:b])
}
